   "date": "1907",
   "title": "《茶花女》",
   "lane": "drama",
   "period": "p0",
   "kind": "话剧",
   "importance": 2,
   "people": [],
   "schools": [],
   "summary": "春柳社在日本东京演出小仲马《茶花女》中的两幕，后又演出曾孝谷根据美国斯陀夫人小说改编的《黑奴吁天录》（七幕剧）。",
   "detail": "旧派小说其时尚有相当的读者。这些旧派小说一律显示了某种过渡的性质，在表达“世变”、“人情”和运用小说形式方面，都显得滞后。而在发挥文化消费功能的同时，又暗暗地为新文学的产生准备了一些条件。比如在作品里输入要求婚恋自主的民主思想、个性主义因素（常与世俗的理解相混合）；部分地吸收外来文学技术。《玉梨魂》接受了《茶花女》的影响，也十分明显。周瘦",
   "memory": "",
   "confuse": "",
   "tags": [
    "常考"
   ],
