   "summary": "《新青年》第4卷第1号出版。从这一号开始，改用白话与新式标点符号。同时编辑部扩大，由有鲁迅、李大钊等参加的《新青年》编辑会同仁轮流值编。",
   "detail": "紧接着，在同年二月号《新青年》上，陈独秀发表了措辞强烈的《文学革命论》，表明了更坚定的文学革命的立场。文中提出“三大主义”作为“文学革命”的征战目标：“曰推倒雕琢的阿谀的贵族文学，建设平易的抒情的国民文学；曰推倒陈腐的铺张的古典文学，建设新鲜的立诚的写实文学；曰推倒迂晦的艰涩的山林文学，建设明了的通俗的社会文学。”陈独秀从内容到形式对封建",
   "memory": "",
   "confuse": "",
   "tags": [
    "常考"
   ],
