   "summary": "李大钊协助《晨报》开辟《马克思研究专栏》。",
   "detail": "稍后出现的另一个影响颇大的文学社团新月社，1923年由胡适、陈源、徐志摩、闻一多、梁实秋等人在北京发起，原是一个文化社交团体，成员大多数曾是旅英美留学生。不久，其内部逐渐形成一个诗人群，由此产生新月诗派，以1926年4月徐志摩在《晨报》副刊上开辟的《诗镌》作为他们代表性的刊物，宣称“要把创格的新诗当作一件认真事情做”。他们所接受的外来文学",
