   "detail": "在文学革命初期和后来的发展阶段，另一些作家也有理论上的贡献，如鲁迅主张白话文运动应当以“灌输正当的学术文艺”并以“改良思想”为“第一事”\r\n \r\n\r\n〔25〕\r\n\r\n\r\n\r\n ，沈雁冰所提出的相对完整的“为人生”的文学观，李大钊初步尝试运用马克思主义解释“什么是新文学”\r\n \r\n\r\n〔26〕\r\n\r\n\r\n\r\n ，郭沫若所提出的注重内在情感自",
