   "detail": "还有两位作者给社会小说增加了滑稽体式。一是徐卓呆，被誉为“文坛笑匠”和“东方卓别林”。他重视写短篇，如《浴堂里的哲学家》、《小说材料批发所》等。1924年发表的短篇《万能术》，融哲理、科幻、寓言于诙谐滑稽的笔调之中，是一部奇作。他在三四十年代仍不断有优秀作品问世。另一位是程瞻庐，他1919年发表的《茶寮小史》、《葫芦》等，以插科打诨的俏皮",
