   "summary": "鲁迅《名字》载7日《晨报副刊》。",
   "detail": "张爱玲（1920—1995年）的出现，是以1943年写出处女作《沉香屑 第一炉香》，经周瘦鹃之手发表于《紫罗兰》的创刊号上为起点的。她出身满清达官显宦的名门，父亲是旧派纨绔子弟，母亲和姑母崇尚西洋文明，为新女性。她就读于上海的教会中学和香港大学，接受了现代的历史观念和文化观念，接受了西方小说的影响，但她8岁读《红楼梦》，一生称赞《海上花列",
