   "summary": "庐隐《一封信》发表于《小说月报》第12卷第6号。",
   "detail": "“问题小说”的作者并不都是纯粹的写实派。有的以后发展为写实主义，但写作“问题小说”的当儿，偏偏是抽象的“爱”与“美”的鼓吹者，是浪漫主义、象征主义色彩皆有的，如冰心、王统照等。至于庐隐，虽写过《一封信》、《灵魂可以卖么》这种真正的“问题小说”，但她很快就显示出感伤的自叙传的小说作风。许地山以注重“人生问题”而走上文坛，但他的小说充满了宗教",
