   "summary": "周作人《美文》发表于8日《晨报副刊》。",
   "detail": "曾经一度加入“左联”的郁达夫，在30年代后，成为出色的山水游记作家。他家乡的富春江因他的优美文字而增光添彩。《屐痕处处》、《达夫游记》集里的作品，如《钓台的春昼》等名篇，脍炙人口。郁达夫移居杭州，寄情山水，但始终未能忘情于社会和民众的现状。他的一无隐饰的忧虑心境还是在凭吊之中透露出来。他自己说要追求“情景兼到，既细且清，而又真切灵活的小品",
