   "detail": "《北望园的春天》一篇堪称佳作，它也采用感伤的抒情笔调，内容却脱出《贺大杰的家宅》，虽写当下的后方生活仍不离东北老乡的圈子，进而去扩大地表现40年代后方政治低气压及这种环境下形成的知识分子和下层卑微人物的孤寂、沉沦和憧憬的内心世界，特别是表现一些善良的小知识分子被生活毁灭的悲剧，被认为富有契诃夫风格。追念总是起源于当前现实生活的，是现实在知",
