   "schools": [],
   "summary": "周作人《“沉沦”》（评论）发表于26日《晨报副刊》。",
   "detail": "郁达夫抒情小说中的病态性欲描写，一向是容易遭到非议的。他注意人的情欲在表达人的内在世界的重要性，试图用一新的眼光，去剖析人的生命和性格中包孕的情欲问题。他受西方人道主义特别是卢梭的“返归自然”思想的影响，主张人的一切合理欲求的自然发展，认为“情欲”作为人的自然天性是应该在文学中得到正视和表现的。加之日本“私小说”里“颂欲”思想和手法的影响",
   "memory": "",
   "confuse": "",
