   "detail": "鲁迅曾谈到自己对新文学的贡献，主要是以创作成就“显示了文学革命的实绩”\r\n \r\n\r\n〔17〕\r\n\r\n\r\n\r\n ，这是确实的：在有了胡适、陈独秀、周作人等的理论的倡导之后，又有了鲁迅这样的作家创造了足以与中国传统文学及世界文学的经典作品并肩而立的现代文学经典，新文学才有可能在中国真正立足、扎根。而鲁迅不仅创造了现代小说的经典《呐喊》、《彷徨",
