   "summary": "冰心《往事》发表于《小说月报》第13卷第10期。",
   "detail": "对于文体，冰心也有自觉的追求，她曾借小说中人物之口说：“我主张‘白话文言化’、‘中文西文化’，这‘化’字大有奥妙，不能道出的，只看作者如何运用罢了，我想如现在的作家如能无形中融合古文和西文，拿来应用于新文学，必能为今日中国的文学界，放一异彩。”\r\n \r\n\r\n〔14〕\r\n\r\n\r\n\r\n 冰心的语言仍浸有旧文学的汁水，不过经过她的处理，已经完全",
   "memory": "",
   "confuse": "",
   "tags": [],
