   "summary": "调离《小说月报》，至商务印书馆国文部。",
   "detail": "首先是白话文的全面推广。“五四”后，各地爱国学生团体纷纷仿效《新青年》、《每周评论》，创办白话报刊，仅1919年就出版400多种，到1920年，连那些最持重的大杂志，如《东方杂志》、《小说月报》，等等，也都采用白话文了。1920年1月，依当时的教育部颁令，凡国民学校低年级国文课教育也统一运用语体文（白话）。“‘文学革命’与‘国语统一’遂呈",
   "memory": "",
