   "title": "《隔绝》",
   "lane": "novel",
   "period": "p1",
   "kind": "",
   "importance": 1,
   "people": [],
   "schools": [],
   "summary": "淦女士《隔绝》发表于《创造》季刊第2卷第2期。",
   "detail": "把解放区的新型小说集中到这一节来专门论述，是因为它们从30年代的左翼小说发展而来，到了这个时候，在一种文艺政策的指导下，与西北广大贫瘠的农村和文化程度远较东南沿海一带城镇低的农民读者相结合，确实将革命现实主义的小说民间化了。这些小说与苏联文学与西方现实主义、浪漫主义文学都有着联系，却与现代主义的世界文学潮流有某种隔绝。它相对形成了自足的体",
   "memory": "",
   "confuse": "",
   "tags": [],
