   "summary": "宗白华《流云》集由亚东图书馆出版。",
   "detail": "抗战时期，京派文人风流云散，布不成阵了。到了1947年6月，朱光潜将《文学杂志》复刊，标志着京派的复出。编者在《复刊卷头语》里明确表明其主张，说文学“是一个国家民族的完整生命的表现”，“文学上只有好坏之别，没有什么新旧左右之别”。这种要建立一种纯正的民族文学的理论，与沈从文的一贯思想相符合。以沈从文创作成就为标志的京派，就这样脱出了三四十",
   "memory": "",
   "confuse": "",
