   "summary": "《在酒楼上》发表于《小说月报》第15卷第5号，收入《彷徨》集。",
   "detail": "《在酒楼上》里“我”有一段自白，特别引人注目：“北方固不是我的旧乡，但南来又只能算一个客子，无论那边的干雪怎样纷飞，这里的柔雪又怎样的依恋，于我都没有什么关系了。”这里所表现的是一种更深沉的无家可归的悬浮感，无可附着的漂泊感。它既表明了中国现代知识分子与“乡土中国”“在”而“不属于”的关系，更揭示了人在“飞向远方、高空”与“落脚于大地”之",
