   "detail": "其他的武侠小说有赵焕亭的《奇侠精忠传》、《大侠殷一官轶事》、《马鹞子全传》等，作风峭拔，注重继承讲史传统而发挥之，从清代故实中杜撰出侠义情节，描摹世态人性皆入情入理。当时便与不肖生并举，世有“南向北赵”之称。还有姚民哀的《山东响马传》、《盐枭残杀记》。前者取材于当时轰动全国的山东临城劫车案，时效性强，又是用第一人称来叙述的，可称绘声绘色，",
