   "summary": "瞿秋白《赤都心史》由商务印书馆出版。",
   "detail": "还有一位较特殊的文学研究会作家是早期共产党人瞿秋白（1899—1935年）。他这时有《饿乡纪程》（即《新俄国游记》）和《赤都心史》问世。这两部散文集是作者以《晨报》特约记者的身份赴苏考察的结晶，根据亲身的见闻向国人真实报道十月革命后的苏俄真相，又留下作者自己的思想印痕。书中并不回避世界上第一个社会主义国家缔造中面临的重重困难，但以深沉的感",
