   "detail": "但新诗仍然在“四面八方的反对声中”站住了脚跟：从1918年《新青年》4卷1号发表第一批新诗（有胡适的《鸽子》、刘半农的《相隔一层纸》、沈尹默的《月夜》等），到1920年胡适的《尝试集》出版，不过三年时间；两年后，胡适就不无欣慰地宣布，他的《尝试集》已经“销售到一万部”，“新诗的讨论时期，渐渐的过去了”\r\n \r\n\r\n〔6〕\r\n\r\n\r\n\r\n ",
