   "summary": "《现代评论》周刊创刊。",
   "detail": "陈西滢（1896—1970年）思想意识上属于徐志摩一派，是《现代评论》上的“闲话家”，创作颇多，后集成《西滢闲话》。他确实是站在“五卅”运动之外、学生与民众运动之上，以貌似公允的姿态评说时事，表明了一种贵族化的立场。不过陈西滢的散文也不乏佳篇，他的特点是行文流畅，有相当的西方文学修养，议论由事出发，富幽默感，当时影响不小。特别是那些介绍知",
   "memory": "",
   "confuse": "",
