   "importance": 2,
   "people": [],
   "schools": [],
   "summary": "至3月《台湾民报》等刊陆续发表倡导新文学运动的文章，并介绍大陆的新文学作品。",
   "detail": "首先应当提到的是被称为“台湾新文学之父”的赖和（1894—1943年）。他最早最有力地激发了台湾新文学的精神，即以现实社会的批判和乡土文化的寻根为本，替本省乡土文学树起了第一面旗帜，并且决定了本省籍作家应走的方向。1926年元旦，赖和在《台湾民报》上发表了白话短篇小说《斗闹热》，\r\n \r\n\r\n〔2〕\r\n\r\n\r\n\r\n 是台湾较早的白话小说，",
   "memory": "",
   "confuse": "",
