   "detail": "人生派写实小说在叶圣陶以外，主要由文学研究会的乡土小说作家群组成。这些作家的成熟作品都产生于“五四”之后，以王鲁彦（《柚子》集1926年出版）、彭家煌（《怂恿》集1927年出版）的成就最大，其他的台静农（《地之子》集1927年出版）、许钦文（《故乡》集1926年出版）、蹇先艾（《朝雾》集1927年出版）、许杰（《惨雾》集1926年出版）等",
