   "summary": "《春莺曲》发表于《创造月刊》第1卷第2期，收入《瓶》。",
   "detail": "写于1925年初春的《瓶》可以说是《女神》与《星空》的诗情在爱情题材上的别一种流露。这里有《女神》式的火山般的热情喷发与奇特想象：诗人由爱极、恋极而想到死，幻想把爱情的化身一枝红梅吞进心头，“梅花在我的尸中，会结成五个梅子，梅子再迸成梅林，啊，我真是永远不死”（《第十六首，春莺曲》）。这是一种浪漫化了的为爱情而献身的精神，与《女神》的时代",
   "memory": "",
   "confuse": "",
   "tags": [],
