   "schools": [],
   "summary": "鲁迅《彷徨》由北新书局出版。",
   "detail": "感伤成了这时期新文学的一种精神标记，映照着“五四”历史转折时期普遍的社会心理。新思潮唤醒了广大青年，但多数人觉醒之后又一时找不到出路，在十字街头彷徨；现代意识促使他们追求人生价值和美好的理想，而黑暗现实的压迫又往往使他们感到苦闷与失望。当然，这种文学上的感伤情调，跟新一代知识者自身的脆弱性及传统文人柔弱心理的习染也是有关的，但作为一种普遍",
   "memory": "",
   "confuse": "",
