   "summary": "约4月任汉口《民国日报》主编。",
   "detail": "1922年成立的浅草社办有《浅草》季刊，并在上海《民国日报》副刊中出过《文艺旬刊》，其骨干成员又于1929年秋组成沉钟社，办有《沉钟》周刊、半月刊，致力于介绍外国文学；特别是德国浪漫主义文学；创作方面则有冯至的诗歌，林如稷、陈炜谟、陈翔鹤的小说，多抒写知识青年苦闷的生活和忧郁的情感，富于感伤的色彩。",
