   "summary": "郁达夫《过去》发表于《创造月刊》第1卷第6期。",
   "detail": "40年代杂文的创作潮流始终受惠于鲁迅的传统。国统区、解放区和上海“孤岛”，都曾经发生过这样的论争，讨论的中心是：鲁迅的时代是不是已经过去？还要不要重振杂文？这些讨论涉及到在抗战的新形势下如何继承、发扬鲁迅散文的现实主义精神问题。",
