   "title": "《坟》",
   "lane": "prose",
   "period": "p1",
   "kind": "散文诗",
   "importance": 1,
   "people": [],
   "schools": [],
   "summary": "鲁迅《坟》集由未名社出版。",
   "detail": "废名的散文化小说对京派文学的渗透力极大。正是他把周作人的文艺观念引至散文以外的领域加以实践。沈从文、何其芳、芦焚等比他稍晚的作家，都从他那里吸收过养料。像沈从文，以后成为更重要的京派小说坛主，却克服了废名的晦涩与狭小的局限，标志着京派的进步。30年代中期继续效仿他的，有王坟、李同愈等，40年代有汪曾祺，显示了废名小说的深长文学价值。",
   "memory": "",
   "confuse": "",
   "tags": [],
