   "summary": "王任叔《监狱》集由光华书局出版。",
   "detail": "小说通过一位作家重归故土，寄居憩园时的所见、所闻、所感，展示了一所大公馆新旧两代主人共同的悲剧命运。旧主人杨老三在嫖赌饮吹中荡尽了祖传的遗产，沦落为乞丐，长期寄生虫式的生活，使他丧失了最起码的谋生能力；根深蒂固的封建等级观念，又使他不屑于自食其力，只好靠偷窃为生，结果在监狱中默默死去。新主人姚国栋又重蹈覆辙，靠父辈的遗产过着庸俗、懒散、奢",
   "memory": "",
   "confuse": "",
