   "summary": "方璧（茅盾）《王鲁彦论》发表于《小说月报》第19卷第1号。在这前后还发表过《鲁迅论》、《读〈倪焕之〉》、《女作家丁玲》、《庐隐论》、《冰心论》、《落花生论》等一系列小说作家作品论。",
