   "summary": "洪灵菲《流亡》（长篇）由现代书局出版。",
   "detail": "作品也如叶紫充溢着深沉的力的、从东北流亡到上海、北平等地的一些青年作者，如萧红、萧军、端木蕻良、舒群、骆宾基、罗烽、白朗、李辉英等人，习惯上被称为“东北作家群”，形成于30年代中期。他们有的未正式加入“左联”，但其创作实际上构成“左联”文学的一部分。正是他们，开了抗日文学的先声，第一次把作家的心血，与东北广袤的黑土、铁蹄下的不屈人民、茂草",
