   "kind": "",
   "importance": 1,
   "people": [],
   "schools": [],
   "summary": "娑婆生（毕倚虹）《人间地狱》由自由杂志社出版。",
   "detail": "夏衍的《包身工》被公认为早期报告文学代表作。作者亲自到上海杨树浦的工厂调查了两个月，搜集了许多素材。作者以阶级分析的眼光，鲜明地表现这完全真实的新闻故事，用细致的描写，揭露出东洋纱厂这个人间地狱里包身工惨绝人寰的生活真相。《包身工》的文学与政治的影响都很深远，像李乔的《锡是如何炼成的》，描写工人的非人处境，明显地与《包身工》一脉相承。",
   "memory": "",
   "confuse": "",
