   "summary": "鲁迅《朝花夕拾》由未名社出版。",
   "detail": "《朝花夕拾》与《野草》一方面在鲁迅的著作中，是最“个人化”的——散文这种文体如周作人所说，本就是“个人的文学之尖端”\r\n \r\n\r\n〔18〕\r\n\r\n\r\n\r\n ；另一方面，又为现代散文的创作提供了两种体式，或者说开创了现代散文的两个创作潮流与传统，即“闲话风”的散文与“独语体”的散文。——在这个方面也是显示了鲁迅“文体家”的特色的。",
