   "summary": "丁玲《在黑暗中》集由开明书店出版。",
   "detail": "《寒夜》写成于1946年底。这是最能代表巴金后期创作风格与水平的一部长篇力作。和以往他的那些小说不同的是，《寒夜》的构思原型不是来自作家自己的生活经历，他是在新婚后不久仍沉浸于甜蜜的幸福之时，纯粹靠想象构思了这个家庭破裂的辛酸故事的。作品描写自由恋爱的知识分子家庭如何在现实生活的重压下破裂，这个寒气肃杀的悲剧发生在抗日战争时期的“陪都”重",
   "memory": "",
   "confuse": "",
   "tags": [],
