   "summary": "鲁迅与冯雪峰等合编的《萌芽》月刊创刊。",
   "detail": "杨逵比较有影响的还有中篇《模范村》、短篇小说《萌芽》和《春光关不住》（又名《压不扁的玫瑰花》）等等。其多数作品都是用日文创作，后译为中文的。杨逵关注现实，参与社会变革，思想开阔，性格豪爽，又受普罗文学思潮影响，其创作大都由现实直逼时代的思想制高点，虽然有浓重的意识形态意味，但视野广远，大气磅礴，有一种粗犷的力度。他的小说，艺术上不算完整，",
   "memory": "",
