   "summary": "《大众文艺》第2卷第3期发表编辑部召开的“文艺大众化座谈会”记录及沈端先、郭沫若、冯乃超、郑伯奇、鲁迅等关于大众化的应征文章。",
   "detail": "1934年夏天还发生过大众语和文字拉丁化的讨论。文艺大众化运动鼓励了创作上的探求，“左联”提倡过工农兵通讯员运动，要求作家创作包括报告文学、演义、唱本、壁报文学在内的多种大众文艺作品，文艺大众化运动是对“五四”文学革命以来“欧化”倾向及革命文学创作中存在的某些“左”的倾向的纠偏，目的在于缩短文学与群众的距离，这本也是无产阶级文学题中应有之",
   "memory": "",
   "confuse": "",
   "tags": [],
