   "detail": "刘呐鸥（1900—1939年）惟一的小说集《都市风景线》，其中的短篇采用“新感觉体”，把当时上海刚形成的现代生活和男女社交情爱场景，尽情摄入。有人指出他“是一位敏感的都市人，操着他的特殊的手腕，他把这飞机、电影、JAZZ、摩天楼、色情（狂）、长型汽车的高速度大量生产的现代生活，下着锐利的解剖刀”\r\n \r\n\r\n〔23〕\r\n\r\n\r\n\r\n 。这",
