   "detail": "《江湖奇侠传》连载不久继之而出的，是顾明道（1897—1944年）自1929到1940年写毕的《荒江女侠》，堪称一部大作品。顾明道从小残疾，是位奇人。他最初写的是言情小说，早期的《啼鹃录》1922年出版，内收18个短篇，多为婚恋哀情题材。1929年后陆续发表长篇悲情小说《美人碧血记》、《红蚕织恨记》、《哀鹣记》，或取材现实，或取材历史，其",
