   "summary": "茅盾《蚀》（《幻灭》、《动摇》、《追求》三部曲）由开明书店出版。",
   "detail": "郭沫若本质上是一个抒情诗人，所以他的作品无一不具诗情。他的散文与小说实在很难严格地区分。《月蚀》、《卖书》，都是通过个人贫困的遭际，向社会发出悲愤呼叫的。《路畔的蔷薇》等六章小品，牧歌式地抒发青春的欢悦与离乡去国的孤寂。他虽然也如郁达夫，习惯于主观情愫的倾泻，但有更多的社会和政治色彩。30年代发表诸多叙述参加革命历程的自传体作品，也可归入",
   "memory": "",
   "confuse": "",
