   "detail": "《啼笑因缘》在社会言情外，又渗进了“武侠”因素。虽然起初是应南方报纸编辑的要求而加写关寿峰、关秀姑父女的，但这不是一个无意的试验。张恨水以一个南方文人久居京华古都，他通俗文学的那种北方气质被南方文化接受并加调理后所形成的特色，也是他的魅力之一。所以他的文字也像“言情”掺和了“侠义”，细腻中挟带了豪爽。他所操的文学形式，质和体都属于章回，但",
