   "summary": "《旧梦》（长篇小说）由商务印书馆出版。",
   "detail": "巴金不再是一味正面抨击封建阶级的角色，他意识到人性与人世变迁的复杂性。在现实批评的同时，他又夹带着对人性弱点的理解与同情，这使得《憩园》形象也比较复杂。如主角杨老三使人厌恶，同时也容易让人产生怜悯。这跟作品着力表现他怀旧与追悔的情绪有关。这种描写有其真实性，客观上也是对封建“长宜子孙”观点的批判。作者立意把这样一个已经彻底堕落的浪子当成一",
