   "detail": "丰子恺（1898—1975年），从20年代中期开始写小品，此时期的散文结集有《缘缘堂随笔》。他的特殊之处是以某种源自佛理的眼光观察生活，于俗相中发现事理，能将琐细的事物叙说得娓娓动听，落笔平易朴实，有赤子之心，如他的画一般，透露着心地光明、一无沾染的品格风貌。作者在看见人世间的昏暗后，企图逃入儿童的世界，加上佛理的渗入，文章萧疏淡远，带着",
