   "detail": "“左联”青年作家的涌现，标志着现代文学在创作上真正结束了“革命文学”的时代而向前迈进了。丁玲显示出横跨两个时期的特色。她的《水》，以及张天翼的《二十一个》、沙汀的《法律外的航线》发表后，给当年的文坛吹入一股劲风，曾被人称为是“新写实主义”的势头。而他们的出现之所以令人瞩目，其主要原因正在于努力扫除概念化地描写身边琐事创作风气，造成了“左联",
