   "summary": "丁玲《水》连载于《北斗》第1卷第1至第3期。",
   "detail": "稍后跃出，但在北方社会言情小说家中可与张恨水相抗衡的是天津的刘云若（1903—1950年）。在总体上，刘云若的成就自然次于张恨水，但有人认为“他的造诣之深，远在张恨水之上”\r\n \r\n\r\n〔7〕\r\n\r\n\r\n\r\n 。这应该是指通俗小说艺术所达到的现代性的程度。刘云若一生在天津度过，以表现北方市民社会为己任。早年编辑过画报和报纸副刊。自1930",
   "memory": "",
   "confuse": "",
