   "people": [],
   "schools": [],
   "summary": "开始创作《子夜》。",
   "detail": "这种意图在完成的《子夜》中虽没有得到完全的体现，但从他创作的整体进行考察，却是基本上实现了的。如果把茅盾的作品按其反映的历史时代先后排列起来看，“五四”运动前后到40年代末近半个世纪内现代中国社会风貌及其变化、各个阶层的生活动向及彼此间的冲突，都得到了充分的艺术反映。可以说，茅盾为我们提供了一部20世纪上半时段中国社会的编年史。",
   "memory": "",
   "confuse": "",
   "tags": [
    "必背"
   ],
