   "summary": "穆时英《南北极》集由湖风书局出版。",
   "detail": "穆时英（1912—1940年），人称“新感觉派的圣手”、“鬼才”等，为一时风行的海派作家。初期的作品收《南北极》集，反映都市下层流浪汉的生活状态，叙述笔调虽短促别致，但还属于写实。从1932年起，写新感觉主义的小说，有了《公墓》、《上海的狐步舞》、《黑牡丹》、《白金的女体塑像》等作品，才完全显示出他的现代派品格。",
   "memory": "",
   "confuse": "",
