   "summary": "施蛰存主编《现代》月刊创刊。",
   "detail": "《现代》主编施蛰存在《现代》4卷1期上发表的《又关于本刊中的诗》几乎可以看作是现代派诗歌的一个宣言：“《现代》中的诗是诗，而且是纯然的现代诗。它们是现代人在现代生活中所感受的现代的情绪，用现代的词藻排列成的现代的诗形。”——这里所强调的，一是要写纯然的“诗”，这就表明了新诗谱系上与早期象征诗派的“纯诗——贵族化的诗”传统的承接；二是写“现",
   "memory": "",
   "confuse": "",
   "tags": [
    "常考"
   ],
