   "detail": "巴金前期小说创作非常丰富，一共写了12部中、长篇小说和60多部短篇小说。题材也比较广泛，有写工人、农民、城市贫民悲苦生活与抗争的（如中篇《砂丁》、《雪》和短篇集《光明集》与《将军集》中的一些作品），但更多更集中的是那些描写青年反抗者、革命者的作品。前期又大体上分为两类：一类是正面描写青年、革命者所从事的社会斗争的，如长篇《灭亡》、《新生》",
   "memory": "",
