   "summary": "重作《新生》。连载于《东方杂志》第4至第11号。次年9月由开明书店出版。",
   "detail": "在《华威先生》发表前后，张天翼还写过《谭九先生的工作》和《“新生”》，都是讽刺的佳构，后一并收入《速写三篇》。《谭九先生的工作》里的地主谭九，是个封建气味浓厚的、未能得志的抗日投机者。至于《“新生”》里的知识分子李逸漠，被抗战打破了隐士梦，想要新生又让旧的生活方式箍得紧紧的，在华威、谭九和抗日民众之间急剧摆动，成为时代的孤独者。作者在写这",
