   "summary": "《春蚕》发表于《现代》第2卷第1期，收入《春蚕》。",
   "detail": "赖和执著地坚持写作“以民众为对象”的作品，他的作品揭露批判殖民统治的不义，充溢着民族的忧愤。1932年初赖和所写的《丰作》和当时大陆上以《春蚕》（茅盾）为代表的写丰收成灾的风气不谋而合。在《丰作》中，老实安分的蔗农添福兄眼见今年甘蔗丰收，正盘算着多卖点钱为儿子娶媳妇，不料把持糖业的制糖会社大幅降低蔗价，乘机盘剥蔗农。蔗农聚众抗议，反遭镇压",
