   "summary": "朱自清《欧游杂记》由开明书店出版。",
   "detail": "此外，这一时期作家们还写了不少国际题材的游记，其中引起读者较大反响的有朱自清的《欧游杂记》、《伦敦杂记》，李健吾的《意大利书简》，郑振铎的《欧行日记》，以及小默（刘思慕）的《欧游漫忆》，胡愈之的《莫斯科印象记》等。这些游记多采用类似随笔的比较自由的写法，虽写的是异域风光，却颇能显示游记作者的个性。朱自清写得较为纪实，在语言的洗练上颇下功夫",
