   "summary": "《雷雨》首次在日本东京演出。",
   "detail": "人们当然不会忘记作者的申明：他所写的是“一首诗”，而不是“社会问题剧”\r\n \r\n\r\n〔2〕\r\n\r\n\r\n\r\n ，“《雷雨》对于我是个诱惑，与《雷雨》俱来的情绪蕴成我对宇宙间许多神秘的事物一种不可言喻的憧憬”\r\n \r\n\r\n〔3〕\r\n\r\n\r\n\r\n 。于是，出现了对《雷雨》的“还原性”的阐释：人们发现与抓住了剧作家在《雷雨》中所揭示的“生命编码”",
   "memory": "",
   "confuse": "",
