   "summary": "熊佛西编导《过渡》在定县农村露天剧场演出，获得成功。",
   "detail": "柳青（1916—1978年）的《种谷记》写在1947年。中国革命还处于新民主主义阶段，但与农村实际生活保持着密切联系的作者，却通过解放区农村在实行减租减息斗争以后，组织互助变工，进行大生产运动的故事，反映了农民生产关系改变的初步状况。欧阳山的《高干大》与柳青的《种谷记》在解放区作品中，起着后来向“社会主义文学”过渡的桥梁作用。这两部作品的",
   "memory": "",
   "confuse": "",
