   "summary": "作《原野》（三幕剧），发表于1937年《文丛》第1卷第2至5期。",
   "detail": "在《雷雨》里已经显露峥嵘的“生命的蛮性”与“复仇”的命题，现在在“原野”（和“雷雨”、“日出”一样，已经成为剧中独立的生命存在）里，终于得到了淋漓尽致的发挥：几十年后，曹禺谈到《原野》时，强调说：“（它）是讲人与人的极爱和极恨的感情，它是抒发一个青年作者情感的一首诗”\r\n \r\n\r\n〔9〕\r\n\r\n\r\n\r\n ，与当年说《雷雨》是“一首诗”竟是",
   "memory": "",
