   "detail": "《故事新编》8篇有5篇写于鲁迅生命的最后时期。面临死亡的威胁，处于内外交困、身心交瘁之中，《故事新编》的总体风格却显示出从未有过的从容、充裕、幽默与洒脱。尽管骨子里仍藏着鲁迅固有的悲凉，却出之以诙谐的“游戏笔墨”。这表明鲁迅的思想与艺术都达到了一个新的境界，具有某种超前性。同时，《故事新编》的试验性也决定了其在艺术上的某种不成熟性，鲁迅在",
