   "detail": "京派的沈从文，抗战以后主要的散文集是《湘西》，比起《湘行散记》来，艺术上更加精熟。《常德的船》、《辰溪的煤》等都是受人称道的佳篇。一方面写尽了湘西的风土人情，一方面比以前更鲜明地表现了下层人民的实际生活状况。这里没有雄浑壮丽的文字，只有细密流动的叙述。",
