   "detail": "赵树理是在对“五四”以来新文学“欧化”倾向进行反省的基础上，建立他那种格外偏重大众化、通俗化的文学主张的，他主要从民间文学中汲取艺术营养，这在解放区作家中也有代表性。他们虽然也在承续“五四”新文学的传统，但和二三十年代诸多新文学作家不同的是，他们与西方文学处于相对隔绝状态。这自然也是战争时期解放区遭受文化封锁的结果。与第一、二代作家，特别",
