   "summary": "《春》第一部一至十章连载于《文季月刊》第1卷第1期，第2卷第1期。",
   "detail": "《家》基本上仍然属于“青春型”的创作，那由真诚热烈的心里唱出的青春之歌，是特别能唤起青年人共鸣的。《家》很能代表巴金前期创作的风格：只求与青年读者情绪沟通，不求深刻隽永，倾向单纯、热情、坦率，以情动人，情感汪洋恣肆，语言流水行云，虽然有时少锤炼，不耐咀嚼，整体上却有一种冲击力，能渗透读者的内心。这种风格自然与巴金激情化的写作状态有关。巴金",
   "memory": "",
   "confuse": "",
   "tags": [],
