   "summary": "卞之琳、孙大雨、梁宗岱、冯至、戴望舒等为编委的《新诗》月刊创刊。",
   "detail": "在发展初期，新诗主要发表在《新青年》、《新潮》、《少年中国》、《星期评论》、《学灯》、《觉悟》等“五四”新文化运动的重要阵地上；第一批白话诗人如胡适、刘半农、周作人、沈尹默、俞平伯、康白情都是新文化运动的骨干，连李大钊、陈独秀、鲁迅也都写过新诗，这都说明了新诗与“五四”思想革命的密切联系。1922年，叶绍钧、刘延陵、朱自清等以“中国新诗社",
   "memory": "",
