   "summary": "发表《作家间需要一种新运动》，引起关于当前创作关于反“差不多”运动的争论。",
   "detail": "1936年10月，沈从文以炯之的笔名在《大公报》文艺副刊上发表《作家间需要一种新运动》，指责文学创作中题材、内容、风格“差不多”现象，其原因在于“记着‘时代’忘了‘艺术’”，号召“作家需要有一种觉悟，明白如果希望作品成为经典，就不宜将它媚悦流俗”\r\n \r\n\r\n〔37〕\r\n\r\n\r\n\r\n 。这种观点引起了众多左翼作家的批评。茅盾在第二年7月发",
