   "summary": "萧红《桥》由文化生活出版社出版。",
   "detail": "王度庐熟悉新文学和西方现代文化思潮。他的武侠小说已以性格心理、性格动作为重心，作者叙述时且有主观情绪的投入。他对江湖恩怨也同白羽一样，能抱批评的态度，如《洛阳豪客》所写。《风尘四杰》富平民思想，用第一人称“我”来叙述，充满对天桥贫民的同情与赞扬，风俗描写逼真，通俗小说形式与纯文学作品的界线已很微小，是十分难得的。",
   "memory": "",
   "confuse": "",
