   "detail": "“左联”后期的作家周文（1907—1952年）也擅长于社会暴露。他一个时期在西康的旧军队里任过文书，所以《雪地》一篇，以描写川康边地风情和军阀的倾轧、丑恶的吏治为其特色。后来的短篇《红丸》，中长篇《烟苗季》、《在白森镇》等，都是沿着这条路子走下来，同时露出讽刺，摆脱了单纯揭发反面人物的写法，掺入了喜剧的因素。此外，写出《达生篇》的万迪鹤，",
