   "summary": "尤兢等集体创作、洪深执笔《咸鱼主义》（独幕剧）发表于《光明》第2卷第3号。",
   "detail": "在“九·一八”事变后，适应建立抗日统一战线的需要，又有“国防戏剧”运动的提倡与发动。所谓“国防戏剧”，除了强调“反帝抗日反汉奸，争取中华民族的解放”的主题外，也还有充分发挥戏剧的宣传（以至现场鼓动）功能的要求，在艺术形式上则“提倡‘通俗化’、‘大众化’和方言话剧”\r\n \r\n\r\n〔1〕\r\n\r\n\r\n\r\n 。这同样也是向着“广场戏剧”的方向发展",
   "memory": "",
   "confuse": "",
   "tags": [],
