   "summary": "沙汀《苦难》集由文化生活出版社出版。",
   "detail": "最能掺和着自己的血泪，从正面表现农民的苦难、觉醒与对生活的期冀，叙事风格也近似茅盾的，是“左联”后期的青年作家叶紫（1912—1939年）。叶紫虽只活了27岁，仅有短短六年的创作生涯，却为革命文学留下了分量不轻的遗产。他写有短篇集《丰收》、《山村一夜》和中篇《星》。酝酿多年的长篇《太阳从西边出来》，以及中篇《菱》都没来得及完笔。他的生命与",
