   "importance": 1,
   "people": [],
   "schools": [],
   "summary": "《北方》发表于《七月》第2集第4期，收《北方》集。",
   "detail": "这时期的另一个特点是南派通俗小说占据上风。由于经济发达和现代出版业、书店业、新闻业在中国东南沿海一带的繁荣，清末的小说就以上海为中心。到了新文学于北方诞生前后，旧派文学作“战略撤退”，它更要依赖江浙城镇的市民读者。苏州有包天笑、周瘦鹃等，扬州有李涵秋、毕倚虹等，他们又都在上海活动，南派的力量雄厚是显然的。以后，张恨水从北方打回南方，北派武",
   "memory": "",
   "confuse": "",
