   "summary": "姚雪垠《差半车麦秸》发表于《文艺阵地》第1卷第3期。",
   "detail": "由单纯地歌颂，一般地赞扬老百姓和青年知识者的抗战积极性，到《文艺阵地》发表姚雪垠的《差半车麦秸》，代表了一种新的潮流，即表现人民尤其是农民，在抗战烽火中得到锻炼，改造自己旧有的国民性性格，并生长出新的素质，成为“新人”。这是抗战小说逐渐深化的一个侧面。",
