   "detail": "萧乾的爱情小说，从处女作《蚕》到他惟一的长篇《梦之谷》，显然都是他经历的写照。他对爱情的体验，几乎构成他一切小说的感情基础，绝不仅仅是对爱情题材起作用。萧乾表明了京派发展本身拥有的多样性。晚出的京派作家，承接了京派传统和时代新意这样两个方面的促进力，京派的松散和宽大，也允许每个作家独立地向前。",
