   "detail": "第二，比小说有更直接的历史感受，因此有更多的感慨和议论。沈从文在散文里说过“‘时间’这个东西十分古怪。一切人一切事都会在时间下被改变”\r\n \r\n\r\n〔17〕\r\n\r\n\r\n\r\n 。而他实际在重返湘西时所看到的，往往与此相反，时间仿佛凝滞了，不动了。绒线铺女孩的女孩和妈妈当年一样出现在作者眼前，“十七年前那小女孩就成天站在铺柜里一堵棉纱边，两手",
