   "summary": "《中国人》报创办，担任副刊“大家看”编辑。",
   "detail": "在本书的历史叙述中，“现代文学”同时还是一个揭示这一时期文学的“现代”性质的概念。所谓“现代文学”，即是“用现代文学语言与文学形式，表达现代中国人的思想、感情、心理的文学”。",
