   "summary": "阿英《碧血花》由上海国民书店初版。",
   "detail": "阿英（钱杏邨）的三大南明史剧：《碧血花》（又名《明末遗恨》、《葛嫩娘》）、《海国英雄》（又名《郑成功》）与《杨娥传》，以及太平天国史剧《洪宣娇》也是这一时期历史剧创作的重要收获，特别是作品写作与演出于上海孤岛那样的特殊环境，产生了异乎寻常的影响。作者笔下的山河破碎的“明末气象”与几个杀身报国的下层奇女子的形象，都是对现实的讽喻，足以激发抗",
   "memory": "",
   "confuse": "",
   "tags": [
    "常考"
   ],
