   "summary": "向林冰在重庆《大公报》副刊《战线》发表《论“民族形式”的中心源泉》，引起国统区文艺界对民族形式问题的讨论。",
   "detail": "30年代的京派以小说创作最显实绩，在沈从文前后涌现出一批具有相当活力的小说家。其中有前述以田园牧歌风著称的废名（冯文炳），有早期写出小说集《谷》而获《大公报》文艺奖金的芦焚。有资深作家杨振声，其时主要精力虽已不再用于小说，但他的文学教育和文学组织作用，使得他的创作精神远播，起到不断凝聚京派内部的作用。加上林徽因、朱光潜组织的两个京派文学沙",
   "memory": "",
   "confuse": "",
