   "schools": [],
   "summary": "《野草》月刊在桂林创刊。",
   "detail": "国统区在艰苦环境下坚持鲁迅杂文传统的，有围绕着文学杂志《野草》形成的以聂绀弩、秦似、夏衍等为代表的杂文作家群。《野草》1940年创刊于桂林，遭当局勒令停刊后迁香港改月刊为旬刊。桂林期间还出过“野草丛书”13种。郭沫若、茅盾等都为它写过文章，秦牧、周而复等青年作者在此崭露头角。还有《新华日报·新华副刊》、《新蜀报·蜀道》等也都登载大量的杂文",
   "memory": "",
   "confuse": "",
   "tags": [
    "必背"
   ],
