   "lane": "prose",
   "period": "p3",
   "kind": "",
   "importance": 1,
   "people": [],
   "schools": [],
   "summary": "萧红《回忆鲁迅先生》由重庆妇女生活书店出版。",
   "detail": "富于才情的萧红这时仍在她的优美散文中写出自己的逆境中的心情，加上抗战中的社会见闻。尤其值得一提的是她的《回忆鲁迅先生》一文，在众多的纪念鲁迅的文字中，向为世人传颂。她写的鲁迅，虽只取一个个的片断，却真实如生地织成一片。",
   "memory": "",
