   "summary": "《树》发表于《诗》月刊第2卷第1期，收《旷野》集。",
   "detail": "当赵树理在解放区的文坛上崭露头角，他的《小二黑结婚》等通俗小说尚未引起知识分子圈子中作家充分认可时，作为共产党文艺政策发言人的评论家周扬就敏锐地指出：“赵树理，他是一个新人，但是一个在创作、思想、生活各方面都有准备的作者，一位在成名之前已经相当成熟了的作家，一位具有新颖独创的大众风格的人民艺术家。”\r\n \r\n\r\n〔1〕\r\n\r\n\r\n\r\n 这",
   "memory": "",
   "confuse": "",
   "tags": [],
