   "detail": "杂文是左翼作家最拿手的文体，但他们同样也钟爱小品散文，在这方面有丰硕的收获。茅盾便是善写小品的重要的散文家。他在进入30年代以后，摆脱了早期《宿莽》中的低沉格调，转而采用与《子夜》相一致的视角和笔法，力图在精短的小品篇幅中也做到全景式地反映广阔的社会生活，思想性和时代性都是极为鲜明的。郁达夫说他：“唯其阅世深了，所以行文每不忘社会。他的观",
