   "title": "《万象》",
   "lane": "kanwu",
   "period": "p3",
   "kind": "散文",
   "importance": 2,
   "people": [],
   "schools": [],
   "summary": "《万象》月刊在上海创刊，陈蝶衣任编辑。",
   "detail": "还有一个王小逸，是当时具有小报情趣的作者。他擅长于言情中暴露社会阴暗，《明月谁家》就是通过由乡村到都市的男女关系来揭示沪上的淫糜风气的。他的《四郊多垒》不用章回，故事也不求连贯，是以散文笔法写的。1942到1943年连载于《万象》的《石榴红》，写冯柳丝兄妹设计惩办“孤岛”恶人，结构、叙事都很现代，又能代表他通过性爱的视角来反映城市人们生活",
   "memory": "",
   "confuse": "",
