   "title": "《家》",
   "lane": "novel",
   "period": "p3",
   "kind": "长篇小说",
   "importance": 3,
   "people": [],
   "schools": [],
   "summary": "根据巴金小说《家》改编四幕话剧《家》。1944年12月由重庆文化生活出版社出版。",
   "detail": "《激流三部曲》中，《家》的成就最高，影响最大。巴金原打算在《家》中写一个旧式大家庭的衰败的历史，写了六章之后，他所挚爱的长兄自杀，这给巴金极大的刺激，他把自己所感受到的黑暗社会的压迫和反抗情绪，集中向旧家庭发泄，虚构了一桩桩血案，更加义无反顾地攻击专制主义。他认为旧家庭所代表的专制制度，扼杀了包括他长兄在内的一切青年的幸福。这种反抗与破坏",
   "memory": "",
   "confuse": "",
   "tags": [
    "必背"
   ],
