   "summary": "张天翼《金鸭帝国》（长篇童话小说）连载于《文艺杂志》第1卷第1至6期，第2卷第1至6期。",
   "detail": "《速写三篇》之外，张天翼还写了长篇讽刺童话《金鸭帝国》，未能完篇便陷入贫病交困之中。他从湖南颠沛流离至重庆、成都，令人惋惜地暂时终止了他的创作生涯，把抗战到解放战争时期讽刺的历史重任，让给了沙汀等人（除了写过少许的讽刺寓言）。张天翼本质上是一个优秀的短篇小说家，凡较长的作品都写得不够精练。他于近百部短篇中，造就出一种善于运用夸张的线条、充",
