   "summary": "白羽《武林争雄记》由正华出版部出版。",
   "detail": "白羽是相当全面的一位武侠小说家。他于武侠中写社会、写情、写“武”的套路、写“侠”的思想境界，都有不同的成就。《武林争雄记》武师丁朝威的女儿丁云秀，及二徒弟袁振武、三徒弟俞剑平这三者之间的爱怨，由于师傅弃长择幼指定掌门人而激化，陡起风波，武与情是融和的（但与王度庐不同，以武为主）。《十二金钱镖》写“杨柳情丝”，尤其是女侠柳叶青的娇痴，都很动",
   "memory": "",
