   "importance": 2,
   "people": [],
   "schools": [],
   "summary": "于伶《长夜行》由桂林新知识书店初版。",
   "detail": "抗战时期于伶（1907—1997年）的主要作品都发表、演出于上海孤岛，代表作《长夜行》却是在国统区的桂林写的。《长夜行》的构思初看似乎很接近夏衍的《上海屋檐下》，也是集中写一栋弄堂房子里的几户人家的性格与命运，但于伶却着重于从平凡中发掘离奇，从离奇中展现主题。于是有了韩英登报征求丈夫的奇事，有了房东（卫志成）与房客（沈春发）互换位置的戏剧",
   "memory": "",
   "confuse": "",
