   "detail": "兼有通俗、先锋品格的作家，还有施济美，写有《凤仪园》、《鬼月》等集子；潘柳黛写有长篇《退职夫人自传》，两人都是40年代后期的上海女性作家。尤其是东方蝃蛛，仅一册《绅士淑女图》，用一种富丽的文字写出十里洋场上旧家族的失落和新的精神家园的难以寻觅，文体雅俗融洽，逼似张爱玲，透出一股繁华中的荒凉况味。东方蝃蝀小说在意象的选择和营造方面，也和张爱",
