   "detail": "郑证因（1900—1960年），在北派中所创的是技击武侠小说一路。他被称为真正懂得武术之人，曾在“北平国术馆”许禹生门下学太极拳，使九环大刀，公开表演献艺。白羽认为他通武术、工文章，两人相交为友，白羽《十二金钱镖》由郑证因开头，郑的初作《武林侠踪》请白羽校改，倒是文坛佳话。1941年《鹰爪王》于当时北方著名的画报《369》上连载，遂名声遐",
