   "summary": "姚克《清宫怨》由上海世界书局出版。",
   "detail": "这一时期的历史剧创作中，也有不注重剧本主题的现实政治意义的，如杨村彬的《清宫外史》（包括《光绪亲政记》与《光绪变政记》两部）、姚克的《清宫怨》，剧作家的主要兴趣在光绪、慈禧各自的复杂性格以及他们之间的思想、情感、心理的交流与撞击上，人物心理剖析的追求是远胜于剧本主题积极性的考虑的。",
