   "detail": "日据时代台湾作家中比较执著地追寻乡土精魂，在艺术上有出色表现的，还有吕赫若（1914—1947年）。1935年发表的他的短篇《牛车》，叙写殖民地工业文明加深了农民的破产和农民的苦难，有如一支悲怆的乡土歌谣。此后又陆续发表有短篇《风水》、中篇《清秋》以及连续小说《庙庭》、《月夜》等。吕赫若常常描写农村日常家庭生活的矛盾或困厄，以此展现社会的",
