   "schools": [],
   "summary": "张爱玲《传奇》由上海杂志社出版。",
   "detail": "但正像上述小说题目所标示的那样，这是“新”的“英雄传奇”：同样是描绘农民（民间）英雄，同样充满英雄主义、浪漫主义情怀与气氛，同样大量采用传奇性的情节，大开大阖，张弛有致的结构，在金戈铁马之中穿插着儿女情长，并同样充分发挥民间口语叙述与描写的生动、活泼、通俗、传神的特长却赋予了革命的新思想、新内容与新色彩。由此而开拓的“革命英雄传奇”的小说",
   "memory": "",
   "confuse": "",
