   "summary": "曾卓《门》集由诗文学社出版。",
   "detail": "温柔的独语，悲哀的独语，或者狂暴的独语。黑色的门紧闭着；一个永远期待的灵魂死在门内，一个永远找寻的灵魂死在门外。每一个灵魂是一个世界，没有窗户。而可爱的灵魂都是倔强的独语者。",
