   "summary": "冯雪峰《乡风与市风》由作家书屋出版。",
   "detail": "曾与鲁迅有密切交往的冯雪峰，兼有诗人、评论家的身份，广泛涉及社会政治症结，写出尖锐的诗的政论。其文笔曲折、深透，而且亲切，充分地展开了杂文的新机能。他善于绵密地说理，偶用比喻，也很新鲜，有历史的脉络与哲理的渗透，表现出语言的浑厚和思想锋利的风格，但他的文字有时不够明快。他的杂文集有《乡风与市风》、《有进无退》、《跨的日子》等。",
