   "detail": "小说家张爱玲的艺术个性在散文中也得到发挥。她这一时期的散文多在《流言》一集中。其中《公寓生活记趣》写城市生活种种凡庸琐事，《更衣记》写清代以来服饰时尚的流变，都很着意写有特征的细节，语气略带调侃，不时融入作者的体验与感觉。如写公寓生活的杂乱和多色味：",
