   "importance": 1,
   "people": [],
   "schools": [],
   "summary": "胡风主编《希望》在重庆创刊。创刊号发表了胡风《置身在为民主的斗争里面》和舒芜的《论主观》。这两篇文章引起了关于现实主义以及“主观”问题的论争。",
   "detail": "剧作家在第二幕的开头与全剧结束时，都精心设置了打夯的小工和他们的歌声，作为“日出”（或拥有与创造“日出”的力量）的象征。剧作家显然从劳动者身上“浩浩荡荡”的“大生命”中看到了希望；而全剧也为“日出”的意象所笼罩，显示出整体的象征性，如同《雷雨》一样：从《雷雨》到《日出》也就保持着内在的一致性。",
   "memory": "",
   "confuse": "",
