   "detail": "郭沫若（1892—1978年）在现代文学史上是足以代表一个时代的诗人与历史剧作家。他是鲁迅在本世纪初热切呼唤、终于出现的摩罗诗人，又是新中国的预言诗人。他的第一本诗集《女神》出版于1921年8月，以崭新的内容与形式，开一代诗风，堪称中国现代新诗的奠基之作。",
