   "detail": "1941年后，战争转入了相持阶段，抗战初起的那种普遍的速胜心态冷静下来，担负传递战争信息和进行抗战宣传的报告文学写作相对减少，但介绍解放区或苏联的文学性通讯多了起来，报告文学的中心转向了解放区。像赵树理叙写边区妇女翻身模范的《孟祥英翻身》，特别以副标题注明是“现实故事”，所取材也是真人真事，用了故事的叙事框架，其实也是属于报告文学的一种。",
