   "detail": "张爱玲散文有意与当时文学主潮拉开距离，只注重以自己的感觉去玩味庸常人生，这种审美层次的“玩味”能给读者带来“一撒手”的阅读快慰。常和张爱玲一起被人们所提起的女作家苏青，在40年代出版过一本散文《浣锦集》，多写妇女的生活感觉，写“乱世中当盛世人”的那种物质性与精神性的追求，平实而直爽，看来很世俗，但又常有一种隽逸透露，其所拥有的主要是一些市",
