   "summary": "作《第四病室》。1946年1月由良友图书公司出版。",
   "detail": "巴金的后期小说创作，从题材上分为两大类：一类是继续顺着《家》的路子写旧家庭没落的，除了《春》和《秋》外，还有《憩园》；另一类是反映抗战时期现实生活的，主要有《火》三部曲、《第四病室》和《寒夜》。这些作品中，中篇《憩园》和长篇《寒夜》是比较受读者欢迎的，这是巴金作品中最富感染力而内涵又较丰厚的作品。",
   "memory": "",
   "confuse": "",
