   "summary": "周而复《地道》发表于《文艺杂志》新1卷第2期。",
   "detail": "在现代文学诸多杰出的作家中，赵树理（1906—1970年）是非常特殊的一位。他是抗日民主根据地和解放区土生土长的作家，有地道的农民气质，能自然自在地写出真正为农民所欢迎的通俗乡土小说，他成功地开创了大众化的创作风尚，代表了40年代解放区文学创作的最高成就。无论从新文学发生以来就始终在探索的大众化课题来看，还是从解放区文学与当代的历史关联来",
