   "detail": "与孙犁一样，以描写农村新的生活、新的人物著称的作家，还有康濯（1920—1991年）。康濯的小说着重从两个不同时代的对比中，表现农民精神世界的变化，家庭成员之间关系的变化。他的代表作有《灾难的明天》、《我的两家房东》等。《我的两家房东》通过农村姑娘金凤和农村干部栓柱的恋爱故事，反映了农民冲决旧婚姻制度、旧传统思想的束缚，开始了思想感情的解",
