   "detail": "随后，在解放区大规模地开展“土地改革”的斗争中，大部分的作家意识到这个大变化所具有的丰富的历史内容、心理内容和审美内容，是富有吸引力的创作天地。解放区作家几乎是在这个伟大运动正在发展的过程中就开始对其进行艺术反映和概括的。解放区作家与现实生活、农民群众之间血肉般的联系的优点在这里得到了最充分的发挥；作家个人感受力、概括力和表现力都受到了考",
