   "summary": "《李家庄的变迁》由华北新华书店出版。后连载于1947年12月18日至1948年3月6日《东北日报》。",
   "detail": "赵树理的有些小说也并不局限于揭示实际生活中的问题，而力图以更阔远的目光去观察近代农村社会的变迁，这类作品的思想内涵更为厚重一些。如中篇小说《李家庄的变迁》即是这一类创作中最优秀的一部。小说描写中国农村的历史变革，描写普通的庄稼汉，如何从自己的亲身体验中，认识并走上革命的道路。小说以山西一个闭塞的小山村为背景，一个朴直的农民铁锁的遭遇为线索",
