   "summary": "陈白尘《升官图》（三幕剧）由群益出版社出版。",
   "detail": "这一时期职业剧作家的创作也带有广场戏剧的特点。吴祖光的《捉鬼传》、宋之的的《群猴》、瞿白音的《南下列车》，以及前一时期创作的陈白尘的《升官图》等，都是学生剧团经常演出的剧目。这时候现实的黑暗用一般的夸张、漫画化手法已不足以表现，于是出现了《捉鬼传》里的荒诞：钟馗遍捉人间诸鬼后，“喜极痛饮，大醉之下，成为化石。千年后钟馗醒来，见鬼蜮之辈复行",
