   "detail": "无名氏（1917—2002年）继徐讦之后，一度成为浪漫爱情小说的畅销书作家。他用“无名书屋”名义出版的“无名丛刊”和“无名书初稿”共计十余种。两套书大致划分出他两个写作阶段。即首先写出一些不注重叙事却文采绚烂的作品，如《露西亚之恋》、《龙窟》（后者为未完长篇的一节），未得到社会注意，抗战时期发表通俗小说《北极风情画》和《塔里的女人》大获成",
