   "summary": "巴金《寒夜》连载于《文艺复兴》第2卷第1至6期。",
   "detail": "《寒夜》特别感人肺腑，这是因为它真实。这是平民的史诗，是战争年代普通知识分子苦难生活的真实图景，是发自小人物内心的真实愤慨。和作者以往许多作品不同的是，用笔更为冷静，很少自己直接出来替主人公呼喊，注意在发掘人物内心冲突方面下工夫。小说构思匠心独运，整部作品都围绕“寒夜”这象征性的氛围做文章，意境凄凉，增强了悲剧效果，又使人很自然联想到作品",
