   "summary": "欧阳予倩作《桃花扇》（三幕话剧），1957年由中国戏剧出版社出版。",
   "detail": "欧阳予倩这时期写有历史剧《忠王李秀成》与《桃花扇》，作品对现实也有所暗示。剧作家在《忠王李秀成·自序》里就提出了剧本的现实性问题：“我写这个戏，对于那种传统的猜忌，力加指摘，不知今日的观众诸君看了那些猜忌的情形，又作何感想？”剧作家关注的中心在于历史人物精神力量的开掘，及对于读者观众的精神感化作用，《忠王李秀成》写作的主旨即在说明“革命者",
   "memory": "",
   "confuse": "",
   "tags": [],
