   "summary": "沙汀《呼嚎》集由上海新群出版社出版。",
   "detail": "抗战胜利前后和解放战争时期，沙汀创作日丰。短篇集《呼嚎》、《医生》，以对四川农村的谙熟程度和高度的政治热情，敲起了蒋家王朝全面覆灭的丧钟。他几乎揭露国民党濒临灭亡前干下的每一件丑行：打内战的不得人心、征兵、征粮、通货膨胀、二五减租骗局、选伪国大、镇压学生运动等等。《范老老师》中出现了国统区人民争民主、反内战的新主题，而正面的农民和小知识者",
   "memory": "",
   "confuse": "",
