   "title": "《结婚》",
   "lane": "novel",
   "period": "p3",
   "kind": "长篇小说",
   "importance": 2,
   "people": [],
   "schools": [],
   "summary": "师陀《结婚》（长篇）由晨光出版公司出版。",
   "detail": "师陀当时陷落在“孤岛”上海，作为京派小说家，由北方穷乡僻壤流落到大城市，像记忆从心底“出土”似的，把悲叹中国乡镇的衰败和人生命运的难以把握两相结合，写出了他的重要中篇《无望村的馆主》，代表性短篇集《果园城记》。后来他虽然进而写都市的癫狂，加重了讽刺性，发表了长篇《结婚》、《马兰》等，但主要成就仍在对河南家乡的哀伤的追忆上。",
   "memory": "",
   "confuse": "",
   "tags": [
    "常考"
   ],
