   "kind": "",
   "importance": 1,
   "people": [],
   "schools": [],
   "summary": "一、本书的修订，主要是吸收1987年以后近十年的研究成果，以及我们自己研究的新的心得，对各章的内容做了较大的变动，而对全书的总体结构，只做个别调整（如作家专章中增补了“沈从文”，将通俗小说的发展独立分章叙述，40年代文学不再分为三个地区分别",
