   "summary": "穆旦《旗》由上海文化生活出版社出版。",
   "detail": "七月诗派是在艾青的影响下，以理论家兼诗人胡风为中心，以《七月》及以后的《希望》、《诗垦地》、《诗创作》、《泥土》、《呼吸》等杂志为基本阵地而形成的青年诗人群，其主要代表诗人有鲁藜、绿原、冀汸、阿垅、曾卓、芦甸、孙钿、方然、牛汉等人，他们以提倡革命现实主义与自由诗体为主要旗帜，在抗日战争与解放战争时期国民党统治区的诗歌创作中产生了巨大影响。",
