   "summary": "周立波《暴风骤雨》上卷由东北书店出版，下卷次年5月出版。",
   "detail": "这两部小说的文学语言也各有特色。《太阳照在桑干河上》的语言细腻，有时失之沉闷，却也不乏优美的篇章。《暴风骤雨》则明快、简净，富有地方特色，充满了农民所特有的幽默感，但有些地方方言口语的运用也失之冷僻。总之，丁玲是在坚持自己的文学探索精神基础上，对农村的新世界投入深深一瞥；而周立波是试图站在民间的地位上，运用政策思想，“仿制”一个接近农民的",
