   "detail": "王度庐（1909—1977年）以悲情武侠著称，使得言情武侠小说旁支斜出又出现新的类型。从1938年后，他连续写下《鹤惊昆仑》、《宝剑金钗》、《剑气珠光》、《卧虎藏龙》、《铁骑银瓶》五部互有联系、又各自独立的武侠小说，成为他的代表作品。王度庐写侠客柔情已经远超出争斗恩怨，五部小说共包括三个悲剧侠情故事：江小鹤（后称江南鹤）和阿鸾、李慕白和俞",
