   "summary": "臧克家、曹辛之、林宏、唐湜、陈敬容、辛笛等以森林出版社名义创刊《中国新诗》月刊，并出版《森林诗丛》。",
   "detail": "在中国新诗史上，郭沫若《女神》曾塑造了具有破坏精神与创造精神的自由解放的抒情主人公形象，那是充分反映了“五四”历史青春期的时代精神的；30年代徐志摩、戴望舒笔下的抒情主人公形象，充满了迷失方向的迷惘、感伤情绪，那是大革命失败以后的历史转折期一部分青年时代情绪的反映；而七月诗派所塑造的行动着的历史的强者的抒情主人公形象则充分反映了经过抗日民",
   "memory": "",
