   "summary": "茅盾、巴金编辑《小说》月刊在香港创刊。",
   "detail": "“问题小说”流行的时间不长，却是典型的“五四”启蒙时代的产物。“问题小说”处在近代社会小说和30年代社会小说之间，人们很容易将它们的承续关系突出，而忽视其中的区别。晚清社会小说可粗分为两类，或事涉国体、政体和社会斗争的，等于是政治小说；而“问题小说”探问人生的终极，关顾每个人的人生价值、生存真谛，它比较地形而上些，“虚”些。问题小说能和以",
