   "summary": "沙汀《还乡记》（长篇）由文化生活出版社出版。",
   "detail": "如何把抗战现实的内容与散文小品这种能够充分表达作者个人性格、心志、感情的艺术形式，完美地结合起来，是许多作家面临的难题。原来的“立达”派散文家，这时能在艺术水准相对保持的情况下，使作品更多地面向社会。丰子恺辑成《率真集》等，他的《辞缘缘堂》、《防空洞中所闻》、《胜利还乡记》，开始描写灾难的中国今日。叶圣陶这时有《未厌居习作》、《西川集》，",
   "memory": "",
   "confuse": "",
