   "summary": "丁玲《太阳照在桑干河上》由东北书店出版。",
   "detail": "丁玲的《太阳照在桑干河上》最大成就在于正确地表现了农村的阶级关系，真实地反映了生活固有的复杂性：一方面，由于作家自觉掌握与运用阶级分析的观点，因此，在表现农村阶级关系的广度、深度及准确度上，都超过了“五四”以来表现农村阶级斗争题材的作品；另一方面，由于作家坚持从生活实际出发，在真实地反映农村阶级关系的复杂性上，在对人性的分析、批判和表达上",
   "memory": "",
   "confuse": "",
