   "summary": "《长河》由上海开明书店出版。",
   "detail": "于是，仅是中长篇能够历数的，就有茅盾的《霜叶红似二月花》、《腐蚀》，老舍的《四世同堂》，巴金的《憩园》、《寒夜》，沙汀的《淘金记》，萧红的《呼兰河传》，沈从文的《长河》，林语堂的《京华烟云》，冯至的《伍子胥》，丁玲的《太阳照在桑干河上》，路翎的《财主底儿女们》，张爱玲的《金锁记》，徐讦的《风萧萧》，钱钟书的《围城》，赵树理的《李有才板话》",
