   "summary": "何其芳《还乡杂记》集由文化生活出版社出版。",
   "detail": "何其芳到解放区后，诗风文风都为之一变，从沉醉幻美转向关注现实，情感粗起来了。写成的散文收入《星火集》，后又有《星火集续编》。这些作品保持着他的深情抒发、沉思和想象交织的特点，同时，渗入了刚健之气。何其芳后期散文的艺术独创性显然不如《画梦录》的时代，但他在国统区写出的一组关于解放区的人物印象记和《还乡杂记》，在当时颇有些影响。何其芳创作的转",
