   "summary": "孔厥、袁静《新儿女英雄传》（长篇）连载于《人民日报》。",
   "detail": "赵树理之外，表现解放区农民武装斗争，而又采取民间喜闻乐见的通俗小说形式的，当时出现过一批模拟旧章回体的新小说。柯蓝的《洋铁桶的故事》描写晋东南地区人民英勇抗战，作品情节比较简单，但充满革命激情。影响更大的是马烽、西戎合作的长篇《吕梁英雄传》与孔厥、袁静的《新儿女英雄传》，分别描写了吕梁山与白洋淀的农民游击战争，人们很容易联想起中国历史上的",
