   "summary": "欧阳山《高干大》（长篇）由北京新华书店出版。",
   "detail": "欧阳山（1908—2000年）的《高干大》是以高生亮这个农民出身的革命干部为中心，写任家沟合作社的发展历史。小说揭示的矛盾是革命共产党人、人民群众与党内官僚主义、主观主义倾向的斗争。作者成功地塑造了中国共产党内农民出身的干部仍然联系群众和迅速官僚化两类典型形象，使得这部作品的意义，远远超出了它所反映的合作社不同发展道路的范围，而作为中国历",
   "memory": "",
   "confuse": "",
