   "summary": "综合理论刊物《学习与批判》在上海创刊，至1976年10月停刊，共出版38期。由上海市委写作组以复旦大学名义主办。刊登大量上海市委写作组以罗思鼎、丁学雷、方岩梁、石仑、石一歌、任犊、宫效闻、康立、梁凌益、齐永红、翟青、方海、戚承楼、金风、靳戈",
