   "title": "逝世",
   "lane": "sichao",
   "period": "p7",
   "kind": "",
   "importance": 1,
   "people": [],
   "schools": [],
   "summary": "逝世。",
   "detail": "在40年代，刘云若的创作颇丰。著名的如《小扬州志》、《旧巷斜阳》、《粉墨筝琶》等，其中表现天津沦陷时期的世态人情，有正义感，写地痞混混儿如何走向汉奸道路，了了分明。回目越写越大，不再刻板地按回目形式分割高潮，而是按情节发展的需要来设置回目。但基本没能超越《红杏出墙记》的模式。如果说张恨水的特点是不断求新，每有新作必出新招，终生探索不止，那",
   "memory": "",
   "confuse": "",
   "tags": [],
